// A boundary is tried once per draft; deleting its capital never forces it again.
export function createSentenceCapitalizer(){let context,previous='',attempted=new Set();return function edit(change){const {before,value,start,end,inputType,data,isComposing,key}=change;if(context!==key||before!==previous){attempted.clear();context=key}let result={value,start,end};if(!isComposing&&inputType==='insertText'&&typeof data==='string'&&[...data].length===1&&/\p{Ll}/u.test(data)&&start===end){const index=start-data.length,prefix=value.slice(0,index);if(/(?:^|[.!?][ \t]+|\n)[ \t"'“‘(\[]*$/u.test(prefix)&&!attempted.has(prefix)){attempted.add(prefix);const upper=data.toLocaleUpperCase();result={value:prefix+upper+value.slice(start),start:index+upper.length,end:index+upper.length}}}previous=result.value;return result}}
const input=typeof document!=='undefined'?document.getElementById('text'):null;
if(input){const edit=createSentenceCapitalizer();let before=input.value;input.addEventListener('beforeinput',()=>{before=input.value});window.DockGroupMeAutoCase={apply(event,key){const desktop=matchMedia('(hover:hover) and (pointer:fine)').matches;const result=edit({before: event?before:input.value,value:input.value,start:input.selectionStart,end:input.selectionEnd,inputType:desktop?event?.inputType:null,data:event?.data,isComposing:event?.isComposing,key});if(result.value!==input.value&&result.value.length<=input.maxLength){input.value=result.value;input.setSelectionRange(result.start,result.end)}before=input.value}}}
